INSERT INTO agency_instructions (id, agency_id, general_instructions, required_documents, created_at, updated_at) VALUES (1, 1, '<h3>CNH DIGITAL:<strong> Será enviado para o seu e-mail com a descrição PORTAL SERVIÇOS em uma semana;</strong></h3><h3>CNH FISICA:<strong> 15 à 20 dias após finalizar as etapas chegará um e-mail avisando que sua CNH estará disponível para retirada;</strong></h3><h3><br></h3><h3><strong>Passo a Passo para gerar as Taxas de Pagamento;</strong></h3><h3><br></h3><h3>1° Passo:<strong> ACESSE: servicos.detran.sc.gov.br/login;</strong></h3><h3>2° Passo:<strong> Faça o LOGIN pela sua conta GOV.BR;</strong></h3><h3>3° Passo:<strong> Clique no botão Consultar Débitos por CPF;</strong></h3><h3>4° Passo:<strong> Clique no botão Consultar meu CPF;</strong></h3><h3>E então será exibida a relação de taxas a pagar. Clique ⬇ para baixar a taxa, ou copie o Código de Barras e realize o pagamento no seu aplicativo do Banco;</h3><h3><strong>Atenção: A taxa tem que ser paga como BOLETO, e não como PIX.</strong></h3>', '', '2025-10-14T23:46:22.718Z', '2025-10-15T02:01:41.358Z');
